import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { FLAG, GK, type DrawingParseResult, type EntityStore } from '@/underlay/entity-store';
import { DxfParseError, isBinaryDxf, parseDxf, sniffDxf } from './index';

/**
 * Reference fixture tests. Fixtures and expectations are generated by
 * scripts/fixtures/make_dxf_fixtures.py (ezdxf); expected block-reference geometry comes from
 * ezdxf's own block explosion, so these tests are independent of the parser's transform code.
 */

const DIR = fileURLToPath(new URL('../../../tests/fixtures/dxf/', import.meta.url));
const read = (f: string) => new Uint8Array(readFileSync(DIR + f));

type Pt = [number, number];
interface EntityExp {
  handle: string;
  insert: string | null;
  tol: number;
  kind: 'LINE' | 'POINT' | 'CIRCLE' | 'ARC' | 'ELLIPSE' | 'POLY' | 'FILL';
  geom?: number[];
  c?: Pt;
  r?: number;
  start?: Pt;
  end?: Pt;
  mid?: Pt;
  points?: Pt[];
  pts?: [number, number, number][];
  closed?: boolean;
  rings?: Pt[][];
  color?: number;
  layer?: string;
  linetype?: string;
  lineweight?: number;
  ltscale?: number;
}
interface TextExp {
  handle: string;
  insert: string | null;
  tol: number;
  text: string;
  anchor: Pt;
  hAlign: number;
  vAlign: number;
  height?: number;
  rotation?: number;
  widthSign?: number;
  hidden?: boolean;
}
interface HatchExp {
  handle: string;
  rings: number;
  pattern: boolean;
  segments: number;
  length: number;
  ringPts?: Pt[][];
  onBoundary?: Pt[];
  offBoundary?: Pt[];
}
interface SplineExp {
  handle: string;
  through?: Pt[];
  tol?: number;
  near?: Pt[];
  nearTol?: number;
  onCircle?: { c: Pt; r: number };
  closed?: boolean;
}
interface EllipsePtsExp {
  handle: string;
  insert: string | null;
  c: Pt;
  points: Pt[];
  tol: number;
  arc?: boolean;
}
interface PropExp {
  handle: string;
  insert: string | null;
  color?: number;
  layer?: string;
  linetype?: string;
  lineweight?: number;
  flags?: number;
  count?: number;
}
interface LayerExp {
  color?: number;
  off: boolean;
  frozen: boolean;
  linetype: string;
  lineweight: number;
  plot: boolean;
}
interface FileExp {
  file: string;
  binary?: boolean;
  sameAs?: string;
  version?: string;
  insunits?: number;
  layouts?: string[];
  layers?: Record<string, LayerExp>;
  counts?: Record<string, number>;
  skipped?: Record<string, number>;
  inserts?: number;
  entities?: EntityExp[];
  texts?: TextExp[];
  hatches?: HatchExp[];
  splines?: SplineExp[];
  ellipsePoints?: EllipsePtsExp[];
  props?: PropExp[];
  colorCounts?: { handle: string; insert: string | null; colors: Record<string, number> }[];
  layoutCounts?: Record<string, Record<string, number>>;
  layoutSkipped?: Record<string, Record<string, number>>;
  warningsContain?: string[];
  extentsContain?: number[];
  extentsWithin?: number[];
  error?: { line: number; contains: string };
}

const EXP = JSON.parse(readFileSync(DIR + 'expectations.json', 'utf8')) as { files: FileExp[] };
const FILES = EXP.files.filter((f) => !f.error);

const cache = new Map<string, DrawingParseResult>();
function parsed(file: string, layout?: string): DrawingParseResult {
  const key = `${file}|${layout ?? ''}`;
  let r = cache.get(key);
  if (!r) {
    r = parseDxf(read(file), { layout });
    cache.set(key, r);
  }
  return r;
}

const geomOf = (s: EntityStore, i: number) =>
  Array.from(s.geom.subarray(s.geomStart[i], s.geomStart[i] + s.geomLen[i]));

/** Store entities with the given handle and top-level reference (null = not from a block). */
function find(s: EntityStore, handle: string, insert: string | null, kind?: number): number[] {
  const out: number[] = [];
  for (let i = 0; i < s.count; i++) {
    if (s.handles[i] !== handle) continue;
    if (kind !== undefined && s.geomKind[i] !== kind) continue;
    const ii = s.insertIndex[i];
    if (insert === null ? ii !== -1 : ii < 0 || s.inserts[ii].handle !== insert) continue;
    out.push(i);
  }
  return out;
}

const close = (a: number, b: number, tol: number) => Math.abs(a - b) <= tol;
const closePt = (a: number[], b: number[], tol: number) => close(a[0], b[0], tol) && close(a[1], b[1], tol);
const TAU = Math.PI * 2;
const norm = (a: number) => ((a % TAU) + TAU) % TAU;
const angDiff = (a: number, b: number) => {
  const d = norm(a - b);
  return Math.min(d, TAU - d);
};
const inCcwRange = (a: number, a0: number, a1: number, tol = 1e-9) => {
  const sweep = norm(a1 - a0) || TAU;
  const rel = norm(a - a0);
  return rel <= sweep + tol || rel >= TAU - tol;
};

function matchesEntity(s: EntityStore, i: number, e: EntityExp): boolean {
  const g = geomOf(s, i);
  const tol = e.tol;
  switch (e.kind) {
    case 'LINE':
    case 'POINT':
    case 'CIRCLE':
      return g.length === e.geom!.length && g.every((v, k) => close(v, e.geom![k], tol));
    case 'ARC': {
      const [cx, cy, r, a0, a1] = g;
      if (!closePt([cx, cy], e.c!, tol) || !close(r, e.r!, tol)) return false;
      const p0 = [cx + r * Math.cos(a0), cy + r * Math.sin(a0)];
      const p1 = [cx + r * Math.cos(a1), cy + r * Math.sin(a1)];
      const ends =
        (closePt(p0, e.start!, tol * 10) && closePt(p1, e.end!, tol * 10)) ||
        (closePt(p0, e.end!, tol * 10) && closePt(p1, e.start!, tol * 10));
      const am = Math.atan2(e.mid![1] - cy, e.mid![0] - cx);
      return ends && close(Math.hypot(e.mid![0] - cx, e.mid![1] - cy), r, tol * 10) && inCcwRange(am, a0, a1);
    }
    case 'ELLIPSE':
      return closePt(g, e.c!, tol) && e.points!.every((p) => onEllipse(g, p, tol * 10, true));
    case 'POLY': {
      const n = g[0];
      if (n !== e.pts!.length) return false;
      if (!!(s.flags[i] & FLAG.CLOSED) !== e.closed) return false;
      return e.pts!.every(
        (p, k) => closePt([g[1 + k * 3], g[2 + k * 3]], p, tol) && close(g[3 + k * 3], p[2], 1e-9),
      );
    }
    case 'FILL': {
      let o = 1;
      for (const ring of e.rings!) {
        const n = g[o++];
        if (n !== ring.length) return false;
        for (let k = 0; k < n; k++, o += 3) if (!closePt([g[o], g[o + 1]], ring[k], tol)) return false;
      }
      return g[0] === e.rings!.length;
    }
  }
  return false;
}

/** Checks that p lies on the stored ellipse (and within its parameter range when `range`). */
function onEllipse(g: number[], p: number[], tol: number, range: boolean): boolean {
  const [cx, cy, mx, my, ratio, t0, t1] = g;
  const nx = -my * ratio;
  const ny = mx * ratio;
  const dx = p[0] - cx;
  const dy = p[1] - cy;
  const u = (dx * mx + dy * my) / (mx * mx + my * my);
  const v = (dx * nx + dy * ny) / (nx * nx + ny * ny);
  const scale = Math.hypot(mx, my);
  if (Math.abs(Math.hypot(u, v) - 1) * scale > tol) return false;
  if (!range || Math.abs(t1 - t0) >= TAU - 1e-12) return true;
  return inCcwRange(Math.atan2(v, u), t0, t1, 1e-7);
}

/** Distance from p to a ring of (x, y, bulge) vertices. */
function distToRing(g: number[], o: number, n: number, p: number[]): number {
  let best = Infinity;
  for (let k = 0; k < n; k++) {
    const x0 = g[o + k * 3];
    const y0 = g[o + k * 3 + 1];
    const b = g[o + k * 3 + 2];
    const j = (k + 1) % n;
    const x1 = g[o + j * 3];
    const y1 = g[o + j * 3 + 1];
    let d: number;
    if (!b) {
      const dx = x1 - x0;
      const dy = y1 - y0;
      const l2 = dx * dx + dy * dy;
      const t = l2 ? Math.max(0, Math.min(1, ((p[0] - x0) * dx + (p[1] - y0) * dy) / l2)) : 0;
      d = Math.hypot(p[0] - x0 - t * dx, p[1] - y0 - t * dy);
    } else {
      const chord = Math.hypot(x1 - x0, y1 - y0);
      const h = (chord / 2) * ((1 - b * b) / (2 * b));
      const cx = (x0 + x1) / 2 - ((y1 - y0) / chord) * h;
      const cy = (y0 + y1) / 2 + ((x1 - x0) / chord) * h;
      const r = Math.hypot(x0 - cx, y0 - cy);
      const a0 = Math.atan2(y0 - cy, x0 - cx);
      const a1 = Math.atan2(y1 - cy, x1 - cx);
      const a = Math.atan2(p[1] - cy, p[0] - cx);
      const inside = b > 0 ? inCcwRange(a, a0, a1) : inCcwRange(a, a1, a0);
      d = inside
        ? Math.abs(Math.hypot(p[0] - cx, p[1] - cy) - r)
        : Math.min(Math.hypot(p[0] - x0, p[1] - y0), Math.hypot(p[0] - x1, p[1] - y1));
    }
    best = Math.min(best, d);
  }
  return best;
}

function distToPolyline(g: number[], p: number[]): number {
  const n = g[0];
  let best = Infinity;
  for (let k = 0; k + 1 < n; k++) {
    const x0 = g[1 + k * 3];
    const y0 = g[2 + k * 3];
    const dx = g[4 + k * 3] - x0;
    const dy = g[5 + k * 3] - y0;
    const l2 = dx * dx + dy * dy;
    const t = l2 ? Math.max(0, Math.min(1, ((p[0] - x0) * dx + (p[1] - y0) * dy) / l2)) : 0;
    best = Math.min(best, Math.hypot(p[0] - x0 - t * dx, p[1] - y0 - t * dy));
  }
  return best;
}

describe('DXF reference fixtures', () => {
  it('fixtures are detected as DXF by signature', () => {
    for (const f of EXP.files) {
      const bytes = read(f.file);
      expect(sniffDxf(bytes), f.file).toBe(true);
      expect(isBinaryDxf(bytes), f.file).toBe(!!f.binary);
    }
  });

  for (const f of FILES) {
    describe(f.file, () => {
      it('header, layouts, counts and skipped entities', () => {
        const r = parsed(f.file);
        expect(r.version).toBe(f.version);
        expect(r.insunits).toBe(f.insunits);
        expect(r.layouts).toEqual(f.layouts);
        expect(r.layout).toBe('Model');
        expect(r.report.counts).toEqual(f.counts);
        expect(r.report.skipped).toEqual(f.skipped ?? {});
        expect(r.report.errors).toEqual([]);
        if (f.inserts !== undefined) expect(r.store.inserts.length).toBe(f.inserts);
        for (const w of f.warningsContain ?? []) expect(r.report.warnings.join('\n')).toContain(w);
        const s = r.store;
        expect(s.handles.length).toBe(s.count);
        for (let i = 0; i < s.count; i++) {
          const o = i * 4;
          expect(s.bbox[o] <= s.bbox[o + 2] && s.bbox[o + 1] <= s.bbox[o + 3]).toBe(true);
        }
      });

      if (f.layers) {
        it('layer table (colour, on/off, frozen, linetype, lineweight, plot)', () => {
          const layers = parsed(f.file).store.layers;
          for (const [name, L] of Object.entries(f.layers!)) {
            const got = layers.find((l) => l.name.toUpperCase() === name.toUpperCase());
            expect(got, name).toBeDefined();
            if (L.color !== undefined) expect(got!.color, name).toBe(L.color);
            expect(got!.off, name).toBe(L.off);
            expect(got!.frozen, name).toBe(L.frozen);
            expect(got!.linetype.toUpperCase(), name).toBe(L.linetype.toUpperCase());
            expect(got!.lineweight, name).toBe(L.lineweight);
            expect(got!.plot, name).toBe(L.plot);
          }
        });
      }

      if (f.entities?.length) {
        it(`geometry of ${f.entities.length} entities (top-level exact; exploded blocks vs ezdxf)`, () => {
          const s = parsed(f.file).store;
          const used = new Set<number>();
          const kinds: Record<string, number> = {
            LINE: GK.LINE,
            POINT: GK.POINT,
            CIRCLE: GK.CIRCLE,
            ARC: GK.ARC,
            ELLIPSE: GK.ELLIPSE,
            POLY: GK.POLY,
            FILL: GK.FILL,
          };
          for (const e of f.entities!) {
            const cands = find(s, e.handle, e.insert, kinds[e.kind]).filter((i) => !used.has(i));
            const hit = cands.find((i) => matchesEntity(s, i, e));
            expect(
              hit,
              `${e.kind} ${e.handle} in ${e.insert}: ${JSON.stringify(e)} vs ${JSON.stringify(cands.map((i) => geomOf(s, i)))}`,
            ).toBeDefined();
            used.add(hit!);
            if (e.color !== undefined) expect(s.color[hit!], `${e.handle} colour`).toBe(e.color);
            if (e.layer !== undefined) expect(s.layers[s.layer[hit!]].name).toBe(e.layer);
            if (e.linetype !== undefined)
              expect(s.linetypes[s.linetype[hit!]].name.toUpperCase()).toBe(e.linetype.toUpperCase());
            if (e.lineweight !== undefined) expect(s.lineweight[hit!]).toBe(e.lineweight);
            if (e.ltscale !== undefined) expect(s.ltscale[hit!]).toBeCloseTo(e.ltscale, 6);
            if (e.insert) expect(s.flags[hit!] & FLAG.IN_BLOCK).toBe(FLAG.IN_BLOCK);
          }
        });
      }

      if (f.texts?.length) {
        it('text content, decoding, anchor and alignment', () => {
          const s = parsed(f.file).store;
          for (const t of f.texts!) {
            const cands = find(s, t.handle, t.insert, GK.TEXT);
            const hit = cands.find(
              (i) => s.texts[s.textIndex[i]] === t.text && closePt(geomOf(s, i), t.anchor, t.tol),
            );
            expect(
              hit,
              `${t.handle} "${t.text}" @${t.anchor}: got ${JSON.stringify(cands.map((i) => [s.texts[s.textIndex[i]], geomOf(s, i)]))}`,
            ).toBeDefined();
            const g = geomOf(s, hit!);
            expect(g[5], `${t.handle} hAlign`).toBe(t.hAlign);
            expect(g[6], `${t.handle} vAlign`).toBe(t.vAlign);
            if (t.height !== undefined) expect(g[2]).toBeCloseTo(t.height, 9);
            if (t.rotation !== undefined)
              expect(angDiff(g[3], t.rotation), `${t.handle} rotation`).toBeLessThan(1e-9);
            if (t.widthSign !== undefined)
              expect(Math.sign(g[4]), `${t.handle} width sign`).toBe(t.widthSign);
            if (t.hidden !== undefined)
              expect(!!(s.flags[hit!] & FLAG.HIDDEN), `${t.handle} hidden`).toBe(t.hidden);
          }
        });
      }

      if (f.hatches?.length) {
        it('hatch boundaries and pattern lines', () => {
          const s = parsed(f.file).store;
          for (const h of f.hatches!) {
            const fills = find(s, h.handle, null, GK.FILL);
            expect(fills.length, h.handle).toBe(1);
            const i = fills[0];
            const g = geomOf(s, i);
            expect(g[0], `${h.handle} rings`).toBe(h.rings);
            expect(!!(s.flags[i] & FLAG.PATTERN)).toBe(h.pattern);
            const lines = find(s, h.handle, null, GK.LINE);
            expect(lines.every((k) => s.flags[k] & FLAG.DERIVED)).toBe(true);
            if (h.pattern) {
              let len = 0;
              for (const k of lines) {
                const [x1, y1, x2, y2] = geomOf(s, k);
                len += Math.hypot(x2 - x1, y2 - y1);
              }
              expect(
                Math.abs(lines.length - h.segments),
                `${h.handle} segments ${lines.length} vs ${h.segments}`,
              ).toBeLessThanOrEqual(Math.max(1, h.segments * 0.02));
              expect(
                Math.abs(len - h.length) / h.length,
                `${h.handle} pattern length ${len} vs ${h.length}`,
              ).toBeLessThan(0.01);
            } else {
              expect(lines.length).toBe(0);
            }
            if (h.ringPts) {
              let o = 1;
              for (const ring of h.ringPts) {
                const n = g[o++];
                expect(n).toBe(ring.length);
                for (let k = 0; k < n; k++, o += 3)
                  expect(closePt([g[o], g[o + 1]], ring[k], 1e-9)).toBe(true);
              }
            }
            for (const p of h.onBoundary ?? []) {
              expect(distToRing(g, 2, g[1], p), `${h.handle} boundary point ${p}`).toBeLessThan(1e-6);
            }
            for (const p of h.offBoundary ?? []) {
              expect(distToRing(g, 2, g[1], p), `${h.handle} not a boundary point ${p}`).toBeGreaterThan(0.1);
            }
          }
        });
      }

      if (f.splines?.length) {
        it('splines are tessellated through their defining points', () => {
          const s = parsed(f.file).store;
          for (const sp of f.splines!) {
            const hits = find(s, sp.handle, null, GK.POLY);
            expect(hits.length, sp.handle).toBe(1);
            const g = geomOf(s, hits[0]);
            const n = g[0];
            expect(n).toBeGreaterThan(8);
            const verts: Pt[] = [];
            for (let k = 0; k < n; k++) verts.push([g[1 + k * 3], g[2 + k * 3]]);
            for (const p of sp.through ?? []) {
              const d = Math.min(...verts.map((v) => Math.hypot(v[0] - p[0], v[1] - p[1])));
              expect(d, `${sp.handle} through ${p}`).toBeLessThan(sp.tol ?? 1e-9);
            }
            for (const p of sp.near ?? [])
              expect(distToPolyline(g, p), `${sp.handle} near ${p}`).toBeLessThan(sp.nearTol!);
            if (sp.onCircle) {
              for (const v of verts)
                expect(
                  Math.abs(Math.hypot(v[0] - sp.onCircle.c[0], v[1] - sp.onCircle.c[1]) - sp.onCircle.r),
                ).toBeLessThan(1e-9);
            }
            if (sp.closed) expect(s.flags[hits[0]] & FLAG.CLOSED).toBe(FLAG.CLOSED);
          }
        });
      }

      if (f.ellipsePoints?.length) {
        it('circles under non-uniform scale / tilted extrusion become ellipses through the projected points', () => {
          const s = parsed(f.file).store;
          for (const e of f.ellipsePoints!) {
            const hits = find(s, e.handle, e.insert, GK.ELLIPSE);
            expect(hits.length, e.handle).toBe(1);
            const g = geomOf(s, hits[0]);
            expect(closePt(g, e.c, e.tol)).toBe(true);
            for (const p of e.points)
              expect(onEllipse(g, p, e.tol, !!e.arc), `${e.handle} point ${p}`).toBe(true);
          }
        });
      }

      if (f.props?.length) {
        it('colour / layer / linetype / lineweight inheritance (BYLAYER, BYBLOCK, layer 0)', () => {
          const s = parsed(f.file).store;
          for (const p of f.props!) {
            const hits = find(s, p.handle, p.insert);
            const label = `${p.handle} in ${p.insert}`;
            if (p.count !== undefined) expect(hits.length, label).toBe(p.count);
            else expect(hits.length, label).toBeGreaterThan(0);
            for (const i of hits) {
              if (p.color !== undefined) expect(s.color[i].toString(16), label).toBe(p.color.toString(16));
              if (p.layer !== undefined) expect(s.layers[s.layer[i]].name, label).toBe(p.layer);
              if (p.linetype !== undefined)
                expect(s.linetypes[s.linetype[i]].name.toUpperCase(), label).toBe(p.linetype.toUpperCase());
              if (p.lineweight !== undefined) expect(s.lineweight[i], label).toBe(p.lineweight);
              if (p.flags !== undefined) expect(s.flags[i] & p.flags, label).toBe(p.flags);
            }
          }
        });
      }

      if (f.colorCounts) {
        it('BYBLOCK colour follows each reference chain', () => {
          const s = parsed(f.file).store;
          for (const c of f.colorCounts!) {
            const got: Record<string, number> = {};
            for (const i of find(s, c.handle, c.insert))
              got[s.color[i].toString(16)] = (got[s.color[i].toString(16)] ?? 0) + 1;
            expect(got).toEqual(c.colors);
          }
        });
      }

      if (f.layoutCounts) {
        it('paper-space layouts parse their own entities', () => {
          for (const [name, counts] of Object.entries(f.layoutCounts!)) {
            const r = parsed(f.file, name);
            expect(r.layout).toBe(name);
            expect(r.report.counts, name).toEqual(counts);
            if (f.layoutSkipped?.[name]) expect(r.report.skipped).toEqual(f.layoutSkipped[name]);
            expect(r.store.count).toBeGreaterThan(0);
          }
        });
      }

      if (f.extentsContain) {
        it('extents are computed from entities', () => {
          const e = parsed(f.file).extents;
          const [a, b, c, d] = f.extentsContain!;
          const [w, x, y, z] = f.extentsWithin!;
          expect(e.minX <= a && e.minY <= b && e.maxX >= c && e.maxY >= d).toBe(true);
          expect(e.minX >= w && e.minY >= x && e.maxX <= y && e.maxY <= z).toBe(true);
        });
      }

      if (f.sameAs) {
        it(`binary DXF gives the same result as ${f.sameAs}`, () => {
          const a = parsed(f.file);
          const b = parsed(f.sameAs!);
          const sa = a.store;
          const sb = b.store;
          expect(sa.count).toBe(sb.count);
          for (const key of [
            'type',
            'geomKind',
            'layer',
            'color',
            'lineweight',
            'linetype',
            'ltscale',
            'flags',
            'geomStart',
            'geomLen',
            'textIndex',
            'insertIndex',
          ] as const) {
            expect(Array.from(sa[key]), key).toEqual(Array.from(sb[key]));
          }
          expect(Array.from(sa.geom)).toEqual(Array.from(sb.geom));
          expect(Array.from(sa.bbox)).toEqual(Array.from(sb.bbox));
          expect(sa.texts).toEqual(sb.texts);
          expect(sa.handles).toEqual(sb.handles);
          expect(sa.layers).toEqual(sb.layers);
          expect(sa.linetypes).toEqual(sb.linetypes);
          expect(sa.inserts).toEqual(sb.inserts);
          expect(a.report).toEqual(b.report);
          expect(a.layouts).toEqual(b.layouts);
        });
      }
    });
  }

  it('large UTM coordinates round-trip exactly (plot plan)', () => {
    const s = parsed('r2018_plotplan.dxf').store;
    const circles: number[][] = [];
    for (let i = 0; i < s.count; i++)
      if (s.geomKind[i] === GK.CIRCLE && s.layers[s.layer[i]].name === 'EQUIPMENT')
        circles.push(geomOf(s, i));
    expect(circles).toEqual([
      [600123.456, 2500087.125, 0.75],
      [600126.789, 2500087.125, 0.75],
      [600130.0625, 2500087.125, 0.75],
    ]);
  });

  it('malformed DXF throws a readable DxfParseError with the line number', () => {
    const f = EXP.files.find((x) => x.error)!;
    let err: unknown;
    try {
      parseDxf(read(f.file));
    } catch (e) {
      err = e;
    }
    expect(err).toBeInstanceOf(DxfParseError);
    const pe = err as DxfParseError;
    expect(pe.line).toBe(f.error!.line);
    expect(pe.message).toContain(f.error!.contains);
    expect(pe.message).toContain(`line ${f.error!.line}`);
  });
});
